package com.drogaria.backend.service;
import com.drogaria.backend.dto.*; import com.drogaria.backend.entity.*; import com.drogaria.backend.exception.ApiException; import com.drogaria.backend.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.List;
@Service public class FavoritoService { private final FavoritoRepository repository; private final ClienteRepository clientes; private final ProdutoRepository produtos; public FavoritoService(FavoritoRepository r,ClienteRepository c,ProdutoRepository p){repository=r;clientes=c;produtos=p;} public List<FavoritoResponse> listar(Integer id){return repository.findByClienteId(id).stream().map(FavoritoResponse::new).toList();} public FavoritoResponse adicionar(FavoritoRequest r){if(repository.findByClienteIdAndProdutoIdProduto(r.getIdCliente(),r.getIdProduto()).isPresent())throw new ApiException("Produto ja esta nos favoritos",HttpStatus.CONFLICT); Favorito f=new Favorito();f.setCliente(clientes.findById(r.getIdCliente()).orElseThrow(()->new ApiException("Cliente nao encontrado",HttpStatus.NOT_FOUND)));f.setProduto(produtos.findById(r.getIdProduto()).orElseThrow(()->new ApiException("Produto nao encontrado",HttpStatus.NOT_FOUND)));f.setDataAdicionado(LocalDate.now());return new FavoritoResponse(repository.save(f));} public void remover(Integer c,Integer p){Favorito f=repository.findByClienteIdAndProdutoIdProduto(c,p).orElseThrow(()->new ApiException("Favorito nao encontrado",HttpStatus.NOT_FOUND));repository.delete(f);} }